reg("db-mushroom-discovery", "The Mushroom Discovery Database", "JAH-MSH-",
    "mushroom record",
    "Real fungi with real science and strict safety: fly agaric, destroying angel (to avoid), oyster, chanterelle, morel, puffball, shiitake — identification, ecology, cultivation, with safety warnings on every entry, 34 complete records.",
    "The Signature system's expanded treatment: the same real fungi carried forward, plus Signature safety-first foraging education, clearly labeled.",
    "Fungi Archivist",
    "mycology guide — teaching real fungal science with strict safety from first principles to advanced topics, using only archive data",
    "Signature fungi analyst — teaching safety-first mycology, clearly labeled",
    "I am the JAH Fungi Archivist. Ask me about mushrooms — safety first — or any of the 34 records.",
    "I am the JAH Signature Fungi Analyst. I teach safety-first mycology — always labeled.",
    "Search mushrooms, fungi, safety...",
    "Ask about mushrooms (safety first)...",
    "Generate clearly-labeled Signature fungi scenarios with safety warnings. Seeded archive records are the authoritative entries.",
    "Seeded mushroom records: 34 complete safety-first records marching toward one million in teaching-ladder order.",
    _mushroom,
    gen_extra="Sample records are complete real fungi entries with safety warnings and real measurement math.",
    health=True)

